.ctb-page-container {
  min-height: 100vh;
  padding: 1.25rem 1rem;
  box-sizing: border-box;
  background-color: #f8fafc;
}

.ctb-content-wrapper {
  max-width: 1400px;
  margin: 0 auto;
}

.ctb-header-section {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  margin-bottom: 1rem;
  padding-top: 0.75rem;
  padding-bottom: 1rem;
}

.ctb-header-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 4rem;
  height: 4rem;
  background: linear-gradient(135deg, #0f172a, #2563eb);
  border-radius: 0.18rem;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.4);
  flex-shrink: 0;
}

.ctb-icon {
  width: 2rem;
  height: 2rem;
  color: #ffffff;
}

.ctb-header-text-group {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.ctb-main-title {
  font-size: 2rem;
  font-weight: 800;
  color: #0f172a;
  margin: 0;
}

.ctb-subtitle {
  font-size: 0.95rem;
  color: #475569;
  margin: 0;
}

.ctb-header-meta {
  margin-left: auto;
  font-size: 0.85rem;
  color: #64748b;
}

.ctb-period span {
  font-weight: 600;
}

.ctb-filters-card {
  background: #ffffff;
  border-radius: 0.25rem;
  box-shadow: 0 16px 40px rgba(15, 23, 42, 0.12);
  border: 1px solid #e2e8f0;
  margin-bottom: 1.5rem;
  overflow: hidden;
}

.ctb-card-header {
  padding: 1rem 1.5rem;
  background: linear-gradient(90deg, #2563eb 0%, #22c55e 100%);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.ctb-card-title {
  font-size: 1rem;
  font-weight: 600;
  color: #ffffff;
  margin: 0;
}

.ctb-filters-content {
  padding: 1.5rem 1.5rem 1.75rem;
}

.ctb-filters-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1.1rem;
  align-items: end;
}

.ctb-filter-group {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.ctb-filter-label {
  font-size: 0.8rem;
  font-weight: 600;
  color: #374151;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.ctb-filter-input,
.ctb-filter-select {
  padding: 0.65rem 0.9rem;
  border-radius: 0.4rem;
  border: 1px solid #d1d5db;
  font-size: 0.85rem;
  background: #ffffff;
  transition: all 0.15s ease;
}

.ctb-filter-input:focus,
.ctb-filter-select:focus {
  outline: none;
  border-color: #2563eb;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.16);
}

.ctb-filter-actions {
  display: flex;
  gap: 0.5rem;
  justify-content: flex-end;
}

.ctb-apply-btn,
.ctb-clear-btn {
  padding: 0.6rem 1.2rem;
  border-radius: 999px;
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all 0.15s ease;
}

.ctb-apply-btn {
  background: #22c55e;
  color: #ffffff;
  box-shadow: 0 4px 10px rgba(34, 197, 94, 0.4);
}

.ctb-apply-btn:hover {
  background: #16a34a;
}

.ctb-clear-btn {
  background: #f3f4f6;
  color: #374151;
  border: 1px solid #d1d5db;
}

.ctb-clear-btn:hover {
  background: #e5e7eb;
}

.ctb-balance-status {
  background: #ffffff;
  border-radius: 0.25rem;
  padding: 1rem 1.75rem;
  margin-bottom: 1.5rem;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  border: 1px solid #e2e8f0;
  text-align: center;
}

.ctb-balanced {
  background: #0f172a;
  color: #ffffff;
}

.ctb-unbalanced {
  background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%);
  color: #ffffff;
}

.ctb-status-text {
  font-size: 1.1rem;
  font-weight: 700;
  margin-right: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  display: inline-block;
}

.ctb-status-details {
  font-size: 0.95rem;
}

.ctb-table-card {
  background: #ffffff;
  border-radius: 0.25rem;
  border: 1px solid #e2e8f0;
  box-shadow: 0 10px 32px rgba(15, 23, 42, 0.12);
  overflow: hidden;
}

.ctb-table-header {
  background: linear-gradient(90deg, #0f172a 0%, #1f2937 100%);
}

.ctb-table-container {
  overflow-x: auto;
}

.ctb-data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.8rem;
}

.ctb-data-table thead {
  background: #f1f5f9;
}

.ctb-data-table th,
.ctb-data-table td {
  padding: 0.6rem 0.75rem;
  border-bottom: 1px solid #e5e7eb;
  text-align: left;
  vertical-align: middle;
}

/* Give the Source column extra room and center the pill */
.ctb-data-table th:first-child,
.ctb-data-table td:first-child {
  width: 4.5rem;
  text-align: center;
  vertical-align: middle;
}

.ctb-source-cell {
  text-align: center;
}

.ctb-data-table th {
  font-weight: 600;
  color: #374151;
}

.ctb-source {
  font-weight: 600;
  font-size: 0.68rem;
  display: inline-block;
  padding: 0.14rem 0.55rem;
  border-radius: 999px;
  min-width: auto;
  margin: 0.25rem auto 0.1rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  border: none;
  transition: transform 0.12s ease, box-shadow 0.12s ease, background 0.12s ease;
  line-height: 1;
}

.ctb-source[data-source='Equity'] {
  background: linear-gradient(135deg, #2563eb 0%, #38bdf8 100%);
  color: #0b1120;
  box-shadow: 0 3px 10px rgba(37, 99, 235, 0.35);
  cursor: pointer;
}

.ctb-source[data-source='GSec'] {
  background: linear-gradient(135deg, #16a34a 0%, #4ade80 100%);
  color: #022c22;
  box-shadow: 0 3px 10px rgba(22, 163, 74, 0.35);
  cursor: pointer;
}

.ctb-source:hover {
  transform: translateY(-1px);
  box-shadow: 0 5px 14px rgba(15, 23, 42, 0.28);
}

.ctb-account-code {
  font-family: 'Courier New', monospace;
  font-weight: 600;
}

.ctb-account-type {
  font-size: 0.75rem;
  text-transform: uppercase;
  color: #6b7280;
}

.ctb-debit,
.ctb-credit,
.ctb-net-balance {
  text-align: right;
  font-family: 'Courier New', monospace;
  font-weight: 600;
}

.ctb-net-balance.positive {
  color: #dc2626;
}

.ctb-net-balance.negative {
  color: #059669;
}

.ctb-no-data {
  padding: 1.5rem;
  text-align: center;
  color: #6b7280;
}

.ctb-loading {
  padding: 3rem 1rem;
  text-align: center;
  color: #4b5563;
}

.ctb-error {
  max-width: 600px;
  margin: 2rem auto;
  background: #fef2f2;
  border-radius: 0.5rem;
  border: 1px solid #fecaca;
  padding: 1.25rem 1.5rem;
  color: #991b1b;
}

.ctb-error-title {
  font-weight: 700;
  margin-bottom: 0.25rem;
}

.ctb-error-message {
  font-size: 0.9rem;
  margin-bottom: 0.75rem;
}

.ctb-retry-btn {
  padding: 0.55rem 1.2rem;
  border-radius: 999px;
  border: none;
  background: #ef4444;
  color: #ffffff;
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
}

.ctb-retry-btn:hover {
  background: #dc2626;
}

@media (max-width: 768px) {
  .ctb-filters-content {
    padding: 1.25rem 1.25rem 1.5rem;
  }

  .ctb-card-header {
    padding: 0.85rem 1.1rem;
  }
}

